import sys
from z3 import *

def solve_golfers(W, G, S):
    # W weeks, G groups, S size
    N = G * S

    # x[w][p] = group of player p in week w
    x = [[Int(f"x_{w}_{p}") for p in range(N)] for w in range(W)]

    s = Solver()

    # Domain
    for w in range(W):
        for p in range(N):
            s.add(x[w][p] >= 0, x[w][p] < G)

    # Group sizes
    for w in range(W):
        for g in range(G):
            s.add(PbEq([(x[w][p] == g, 1) for p in range(N)], S))

    # No two players in the same group more than once
    for p1 in range(N):
        for p2 in range(p1 + 1, N):
            s.add(PbLe([(x[w][p1] == x[w][p2], 1) for w in range(W)], 1))

    # Symmetry breaking
    # Week 0: player p is in group p // S
    for p in range(N):
        s.add(x[0][p] == p // S)

    # Player 0 is always in group 0
    for w in range(W):
        s.add(x[w][0] == 0)

    # Order of groups in each week (by first element)
    # Actually, we can just fix the first player of each group in week 1? No, players can be anywhere.
    # Let's just use a simple symmetry breaking:
    # For week w, group g, the minimum player in group g is less than the minimum player in group g+1
    # This is already satisfied for week 0.
    for w in range(1, W):
        for g in range(G - 1):
            # We can't easily express min player in Z3 without extra variables.
            pass

    # Lexicographical ordering of weeks?

    s.set("timeout", 30000)
    if s.check() == sat:
        m = s.model()
        res = []
        for w in range(W):
            for p in range(N):
                res.append(m.evaluate(x[w][p]).as_long())
        print("SAT")
        print(res)
    else:
        print("UNSAT or TIMEOUT")

solve_golfers(7, 9, 3)

def generate_sgp_27_3_7():
    # Points are 0 to 26, representing (x, y, z) in GF(3)^3
    # x, y, z in {0, 1, 2}
    def to_point(x, y, z):
        return x * 9 + y * 3 + z

    def from_point(p):
        return p // 9, (p // 3) % 3, p % 3

    # Directions are non-zero vectors in GF(3)^3, up to scaling
    directions = []
    for x in range(3):
        for y in range(3):
            for z in range(3):
                if x == 0 and y == 0 and z == 0:
                    continue
                # Normalize direction: first non-zero coordinate must be 1
                if x != 0:
                    if x == 2: continue
                elif y != 0:
                    if y == 2: continue
                elif z != 0:
                    if z == 2: continue
                directions.append((x, y, z))

    assert len(directions) == 13

    weeks = []
    for d in directions[:7]: # Pick first 7 directions
        dx, dy, dz = d
        used = [False] * 27
        groups = []
        for p in range(27):
            if not used[p]:
                px, py, pz = from_point(p)
                group = []
                for t in range(3):
                    nx = (px + t * dx) % 3
                    ny = (py + t * dy) % 3
                    nz = (pz + t * dz) % 3
                    np = to_point(nx, ny, nz)
                    group.append(np)
                    used[np] = True
                groups.append(group)
        weeks.append(groups)

    # Format as flat list: entry w*27 + p gives the group (in 0..8) of golfer p in week w
    result = [0] * (7 * 27)
    for w in range(7):
        for g_idx, group in enumerate(weeks[w]):
            for p in group:
                result[w * 27 + p] = g_idx

    print(result)

