def verify(res):
    W = 7
    G = 9
    S = 3
    N = 27

    # Check lengths
    if len(res) != W * N:
        print("Wrong length")
        return False

    # Check group sizes
    for w in range(W):
        counts = [0] * G
        for p in range(N):
            counts[res[w * N + p]] += 1
        if any(c != S for c in counts):
            print(f"Wrong group sizes in week {w}: {counts}")
            return False

    # Check pairs
    pairs = set()
    for w in range(W):
        groups = [[] for _ in range(G)]
        for p in range(N):
            groups[res[w * N + p]].append(p)

        for g in groups:
            for i in range(len(g)):
                for j in range(i + 1, len(g)):
                    p1, p2 = g[i], g[j]
                    if p1 > p2:
                        p1, p2 = p2, p1
                    if (p1, p2) in pairs:
                        print(f"Pair {(p1, p2)} repeated in week {w}")
                        return False
                    pairs.add((p1, p2))

    print("Valid!")
    return True

